import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>
#define THREADS 256
#define CHUNKS 8
__global__ void triplet_partial_kernel(const float4* __restrict__ anchor,
                                        const float4* __restrict__ positive,
                                        const float4* __restrict__ negative,
                                        float* __restrict__ sum_pos_arr,
                                        float* __restrict__ sum_neg_arr,
                                        int batch_size,
                                        int dim4) {
    int row = blockIdx.x;
    if (row >= batch_size) return;
    const float4* a = anchor + (size_t)row * dim4;
    const float4* p = positive + (size_t)row * dim4;
    const float4* n = negative + (size_t)row * dim4;
    float sum_pos = 0.0f;
    float sum_neg = 0.0f;
    for (int i = threadIdx.x; i < dim4; i += blockDim.x) {
        float4 av = a[i];
        float4 pv = p[i];
        float4 nv = n[i];
        float dpx = av.x - pv.x;
        float dpy = av.y - pv.y;
        float dpz = av.z - pv.z;
        float dpw = av.w - pv.w;
        float dnx = av.x - nv.x;
        float dny = av.y - nv.y;
        float dnz = av.z - nv.z;
        float dnw = av.w - nv.w;
        sum_pos += dpx * dpx + dpy * dpy + dpz * dpz + dpw * dpw;
        sum_neg += dnx * dnx + dny * dny + dnz * dnz + dnw * dnw;
    }
    unsigned mask = 0xffffffff;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum_pos += __shfl_down_sync(mask, sum_pos, offset);
        sum_neg += __shfl_down_sync(mask, sum_neg, offset);
    }
    __shared__ float warp_pos[THREADS / 32];
    __shared__ float warp_neg[THREADS / 32];
    int warp_id = threadIdx.x / 32;
    int lane_id = threadIdx.x % 32;
    if (lane_id == 0) {
        warp_pos[warp_id] = sum_pos;
        warp_neg[warp_id] = sum_neg;
    }
    __syncthreads();
    if (warp_id == 0) {
        float p = (lane_id < THREADS / 32) ? warp_pos[lane_id] : 0.0f;
        float n = (lane_id < THREADS / 32) ? warp_neg[lane_id] : 0.0f;
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            p += __shfl_down_sync(mask, p, offset);
            n += __shfl_down_sync(mask, n, offset);
        }
        if (lane_id == 0) {
            sum_pos_arr[row] = p;
            sum_neg_arr[row] = n;
        }
    }
}
__global__ void finalize_reduce_kernel(const float* __restrict__ sum_pos_arr,
                                        const float* __restrict__ sum_neg_arr,
                                        float* __restrict__ out,
                                        int batch_size,
                                        float margin) {
    __shared__ float shared[THREADS];
    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + tid;
    float sum = 0.0f;
    for (int row = idx; row < batch_size; row += blockDim.x * gridDim.x) {
        float d_pos = sqrtf(sum_pos_arr[row]);
        float d_neg = sqrtf(sum_neg_arr[row]);
        float l = d_pos - d_neg + margin;
        sum += l > 0.0f ? l : 0.0f;
    }
    shared[tid] = sum;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared[tid] += shared[tid + s];
        }
        __syncthreads();
    }
    if (tid == 0) {
        atomicAdd(out, shared[0] / batch_size);
    }
}
torch::Tensor triplet_margin_loss_cuda(torch::Tensor anchor,
                                        torch::Tensor positive,
                                        torch::Tensor negative,
                                        double margin) {
    TORCH_CHECK(anchor.is_cuda(), "anchor must be a CUDA tensor");
    TORCH_CHECK(positive.is_cuda(), "positive must be a CUDA tensor");
    TORCH_CHECK(negative.is_cuda(), "negative must be a CUDA tensor");
    anchor = anchor.contiguous();
    positive = positive.contiguous();
    negative = negative.contiguous();
    int batch_size = anchor.size(0);
    int dim = anchor.size(1);
    TORCH_CHECK(dim % 4 == 0, "dim must be divisible by 4 for vectorized kernel");
    int dim4 = dim / 4;
    auto stream = at::cuda::getCurrentCUDAStream();
    auto sum_pos_arr = torch::empty({batch_size}, anchor.options());
    auto sum_neg_arr = torch::empty({batch_size}, anchor.options());
    dim3 grid(batch_size);
    dim3 block(THREADS);
    triplet_partial_kernel<<<grid, block, 0, stream>>>(
        reinterpret_cast<const float4*>(anchor.data_ptr<float>()),
        reinterpret_cast<const float4*>(positive.data_ptr<float>()),
        reinterpret_cast<const float4*>(negative.data_ptr<float>()),
        sum_pos_arr.data_ptr<float>(),
        sum_neg_arr.data_ptr<float>(),
        batch_size,
        dim4
    );
    auto loss_sum = torch::empty({1}, anchor.options());
    cudaMemsetAsync(loss_sum.data_ptr<float>(), 0, sizeof(float), stream);
    int reduce_blocks = (batch_size + THREADS - 1) / THREADS;
    if (reduce_blocks > 1024) reduce_blocks = 1024;
    if (reduce_blocks < 1) reduce_blocks = 1;
    finalize_reduce_kernel<<<reduce_blocks, THREADS, 0, stream>>>(
        sum_pos_arr.data_ptr<float>(),
        sum_neg_arr.data_ptr<float>(),
        loss_sum.data_ptr<float>(),
        batch_size,
        (float)margin
    );
    auto loss = loss_sum;
    return loss.squeeze();
}
'''
